async (cursor, num, params) => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const pageStart = Date.now();
  const shown = sel => [...document.querySelectorAll(sel)].find(e => e.getClientRects().length) || null;
  const INPUT = 'rich-textarea [role="textbox"][contenteditable="true"]';
  const label = (...ls) => [...document.querySelectorAll('button')].find(b => b.getClientRects().length && ls.includes(b.getAttribute('aria-label')));
  const responses = () => [...document.querySelectorAll('model-response')].filter(e => e.getClientRects().length);
  const queries = () => [...document.querySelectorAll('user-query')].filter(e => e.getClientRects().length);
  // 一轮回复收尾的标志：底下出现「答得好 / 重做」那排按钮（生成途中没有）
  const finished = m => !!m && [...m.querySelectorAll('button')].some(b => /^(答得好|答得不好|重做|Good response|Bad response|Redo)$/.test(b.getAttribute('aria-label') || ''));
  const busy = () => !!label('停止回答', 'Stop response');
  const genImgs = m => m ? [...m.querySelectorAll('generated-image img, single-image img, img')].filter(i => i.complete && i.naturalWidth >= 256 && i.getClientRects().length && !(window.__gmiBefore && window.__gmiBefore.has(i.currentSrc || i.src))) : [];
  const QUOTA = /已达到.{0,12}(上限|限额)|limit (for today|reached)|额度已用完|明天再|try again tomorrow|reached your/i;
  if (!cursor) {
    let ed = null;
    for (let i = 0; i < 30 && !(ed = shown(INPUT)); i++) await sleep(300);
    if (!ed) throw new Error('[gemini-image] 没找到输入框 url=' + location.pathname);
    // 常驻标签：上一轮停在 /app/<对话 id>。点侧栏「发起新对话」开新对话（页内跳转，不整页重载）
    if (queries().length || /^\/app\/./.test(location.pathname)) {
      // 「发起新对话」有两个入口（左上角 a[href="/"]、侧栏 a[href="/app"]），侧栏收起时有的看不见、点了没反应（2026-10-22 一次停在旧对话上）：
      // 看得见的逐个点，4s 还在旧对话就整页去 /app（少见）
      const stale = () => queries().length || /^\/app\/./.test(location.pathname) || !shown(INPUT);
      const ncs = [...document.querySelectorAll('[data-test-id="new-chat-button"] a, a[aria-label="发起新对话"], a[aria-label="New chat"], button[aria-label="发起新对话"], button[aria-label="New chat"]')].filter(e => e.getClientRects().length);
      for (const nc of ncs) {
        nc.click();
        const t1 = Date.now();
        while (Date.now() - t1 < 4000 && stale()) await sleep(300);
        if (!stale()) break;
      }
      if (stale()) {
        location.assign('/app');
        throw new Error('[gemini-image] 点「发起新对话」没换页，已整页打开 /app，下一轮再来');
      }
      if (queries().length) throw new Error('[gemini-image] 点了「发起新对话」，页面上还是上一条对话 url=' + location.pathname);
      ed = shown(INPUT);
      if (!ed) throw new Error('[gemini-image] 开了新对话却没找到输入框');
    }
    // 选上「制作图片」工具（输入框下面多一个「图片」chip，按钮 aria-label「取消选择“图片”」）
    const imgOn = () => !![...document.querySelectorAll('button')].find(b => b.getClientRects().length && /取消选择“图片”|Deselect.*Image/i.test(b.getAttribute('aria-label') || ''));
    if (!imgOn()) {
      const tools = label('上传和工具', 'Upload files and tools', 'Tools', '工具');
      if (!tools) throw new Error('[gemini-image] 没找到「上传和工具」按钮');
      tools.click();
      let item = null;
      for (let i = 0; i < 15 && !item; i++) { await sleep(200); item = [...document.querySelectorAll('.cdk-overlay-container button, .cdk-overlay-container [role^="menuitem"]')].find(e => /^(制作图片|Create image|Create images)$/.test(e.innerText.trim())); }
      if (!item) throw new Error('[gemini-image] 工具菜单里没有「制作图片」');
      item.click();
      for (let i = 0; i < 15 && !imgOn(); i++) await sleep(200);
      if (!imgOn()) throw new Error('[gemini-image] 点了「制作图片」，输入框下面没出现「图片」');
      ed = shown(INPUT) || ed;
    }
    // 参考图（图生图）：当剪贴板文件粘进输入框，等缩略图出来、上传转圈没了，再写字
    if (params.images) {
      const urls = params.images.split('\n').filter(Boolean);
      const fdt = new DataTransfer();
      for (let i = 0; i < urls.length; i++) { const m = /^data:([^;,]+)?(;base64)?,(.*)$/s.exec(urls[i]); if (!m) throw new Error('[gemini-image] 参考图要 data URL'); const type = m[1] || 'image/png'; const bin = m[2] ? atob(m[3]) : decodeURIComponent(m[3]); const bytes = new Uint8Array(bin.length); for (let k = 0; k < bin.length; k++) bytes[k] = bin.charCodeAt(k); fdt.items.add(new File([bytes], 'ref' + i + '.' + (type.split('/')[1] || 'png'), { type })); }
      const area = () => ed.closest('fieldset, input-area-v2, .input-area, form') || document;
      const thumbs = () => [...area().querySelectorAll('img')].filter(i => i.getClientRects().length).length;
      const before = thumbs();
      // 合成的 paste / drop 事件 Gemini 都不接（2026-10-22 实测）。走「上传和工具 → 上传文件」：它临时建一个 input[type=file] 再 .click() 弹系统选择框，
      // 这里把 .click() 拦下来不弹框，直接把文件塞给它、派 change
      let cap = null;
      const origClick = HTMLInputElement.prototype.click;
      HTMLInputElement.prototype.click = function () { if (this.type === 'file') { cap = this; return; } return origClick.call(this); };
      try {
        const tools = label('上传和工具', 'Upload files and tools', 'Tools', '工具');
        if (!tools) throw new Error('[gemini-image] 没找到「上传和工具」按钮');
        tools.click();
        let up = null;
        for (let i = 0; i < 15 && !up; i++) { await sleep(200); up = [...document.querySelectorAll('.cdk-overlay-container button, .cdk-overlay-container [role^="menuitem"]')].find(e => e.getClientRects().length && /^(上传文件|Upload files)/.test(e.innerText.trim())); }
        if (!up) throw new Error('[gemini-image] 工具菜单里没有「上传文件」');
        up.click();
        for (let i = 0; i < 20 && !cap; i++) {
          await sleep(150);
          // 第一次上传会弹「根据图片和文件生成内容……同意」的条款框：要用户自己在 Gemini 标签上点一次「同意」，不替他点
          if (/根据图片和文件生成内容|Generate content from images and files/.test((document.querySelector('.cdk-overlay-container') || {}).innerText || '')) {
            const cancel = [...document.querySelectorAll('.cdk-overlay-container button')].find(x => x.getClientRects().length && /^(取消|Cancel)$/.test(x.innerText.trim()));
            if (cancel) cancel.click();
            throw new Error('[gemini-image] Gemini 第一次上传图片要同意条款（「根据图片和文件生成内容」）：请在 Gemini 标签上手动上传一次图片、点「同意」');
          }
        }
      } finally { HTMLInputElement.prototype.click = origClick; }
      if (!cap) throw new Error('[gemini-image] 点了「上传文件」，没等到上传框');
      cap.files = fdt.files;
      cap.dispatchEvent(new Event('change', { bubbles: true }));
      for (let i = 0; i < 30 && thumbs() < before + urls.length; i++) await sleep(300);
      if (thumbs() < before + urls.length) throw new Error('[gemini-image] 参考图没挂到输入框上（输入框里没看到缩略图）');
      const uploading = () => !!area().querySelector('mat-progress-spinner, mat-spinner, [role="progressbar"]');
      const tU = Date.now();
      while (uploading() && Date.now() - tU < 20000) await sleep(300);
      if (uploading()) throw new Error('[gemini-image] 参考图 20s 内没传完');
    }
    // 写字：Quill 编辑器不接合成的 paste 事件（2026-10-22 实测粘进去 0 字），execCommand insertText 可以
    const text = '请直接画一张方形（1:1）的图，不要提问、不要解释，只出图：\n' + params.prompt;
    ed.focus();
    document.execCommand('insertText', false, text);
    let send = null;
    const t0 = Date.now();
    while (Date.now() - t0 < 10000) {
      send = label('发送', 'Send message', 'Send');
      if (send && !send.disabled && send.getAttribute('aria-disabled') !== 'true') break;
      await sleep(300);
    }
    if (!send || send.disabled) throw new Error('[gemini-image] 写入后 10s 发送按钮仍不可用（输入框字数 ' + ed.innerText.length + '）');
    window.__gmiBefore = new Set([...document.querySelectorAll('img')].map(i => i.currentSrc || i.src));
    send.click();
    for (let i = 0; i < 20 && !queries().length; i++) await sleep(300);
    if (!queries().length) throw new Error('[gemini-image] 点了发送，消息没发出去');
    window.__gmiT0 = Date.now();
    window.__gmiSrc = null; window.__gmiSince = 0; window.__gmiTxt = null; window.__gmiTxtSince = 0;
  }
  const deadline = Math.min(Date.now() + 22000, pageStart + 26000);
  while (Date.now() < deadline) {
    const m = responses().at(-1);
    const img = genImgs(m).at(-1);
    const done = finished(m) && !busy();
    if (img && done) {
      const src = img.currentSrc || img.src;
      if (src !== window.__gmiSrc) { window.__gmiSrc = src; window.__gmiSince = Date.now(); }
      else if (Date.now() - window.__gmiSince > 2000) {
        // 图是 blob:，页内 fetch 会被 CSP 拦（2026-10-22 实测 Failed to fetch）；直接画进 canvas（同源 blob 不污染画布）
        const k = Math.min(1, 1024 / Math.max(img.naturalWidth, img.naturalHeight));
        const c = document.createElement('canvas');
        c.width = Math.round(img.naturalWidth * k); c.height = Math.round(img.naturalHeight * k);
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        const png = c.toDataURL('image/png').split(',')[1];
        return { items: [{ guid: 'gm' + location.pathname.split('/').pop() + '-' + Date.now(), png, index: '0' }], cursor: '' };
      }
    } else if (!img && done && m) {
      // 只回了文字（拒绝 / 额度用完 / 反问）：收尾了、文字 5s 不变，就把它说的话抛出来
      const txt = (m.innerText || '').replace(/^Gemini 说\s*/, '').trim();
      if (txt === window.__gmiTxt) {
        if (Date.now() - window.__gmiTxtSince > 5000) throw new Error('[gemini-image] Gemini ' + (QUOTA.test(txt) ? '额度用完了：' : '只回了文字、没出图：') + txt.slice(0, 200));
      } else { window.__gmiTxt = txt; window.__gmiTxtSince = Date.now(); }
    }
    await sleep(500);
  }
  if (Date.now() - (window.__gmiT0 || pageStart) > 190000) throw new Error('[gemini-image] 190s 内没等到图');
  return { items: [], pending: true, cursor: String(Number(cursor || 0) + 1) };
}
